def clamp(value, lo, hi):
    """Return value clamped between lo and hi."""
    # BUG: clamps in wrong direction
    if value < lo:
        return hi
    if value > hi:
        return lo
    return value


def safe_divide(a, b, default=0):
    """Divide a by b; return default if b is zero."""
    # BUG: ignores default, always raises
    return a / b


def moving_average(values, window):
    """Compute trailing moving average with given window size."""
    if not values or window <= 0:
        return []
    result = []
    for i in range(len(values)):
        start = max(0, i - window + 1)
        # BUG: off-by-one, uses start-1
        chunk = values[start - 1:i + 1]
        result.append(sum(chunk) / len(chunk))
    return result

