import pytest
from math_utils import clamp, safe_divide, moving_average

def test_clamp_below():
    assert clamp(1, 5, 10) == 5

def test_clamp_above():
    assert clamp(15, 5, 10) == 10

def test_clamp_within():
    assert clamp(7, 5, 10) == 7

def test_safe_divide_normal():
    assert safe_divide(10, 2) == 5.0

def test_safe_divide_zero():
    assert safe_divide(10, 0) == 0
    assert safe_divide(10, 0, default=-1) == -1

def test_moving_average_basic():
    result = moving_average([1, 2, 3, 4, 5], 3)
    assert result[2] == pytest.approx(2.0)  # avg of 1,2,3
    assert result[4] == pytest.approx(4.0)  # avg of 3,4,5

def test_moving_average_empty():
    assert moving_average([], 3) == []
